input.command:
$item = Get-Item E:\Claude\.claude -ErrorAction SilentlyContinue
Write-Output "Attributes: $($item.Attributes)"
Write-Output "LinkType: $($item.LinkType)"
Write-Output "Target: $($item.Target)"

# Also check each subdirectory
Get-ChildItem E:\Claude\.claude -Directory | ForEach-Object {
    $sub = Get-Item $_.FullName
    if ($sub.LinkType) {
        Write-Output "JUNCTION: $($sub.Name) -> $($sub.Target)"
    }
}
